import{_ as a,o as i,c as e,ag as n}from"./chunks/framework.C9sp7nFj.js";const r=JSON.parse('{"title":"为什么 0.1 + 0.2 !== 0.3","description":"","frontmatter":{},"headers":[],"relativePath":"basis/other/0.1-plus-0.2.md","filePath":"basis/other/0.1-plus-0.2.md"}'),t={name:"basis/other/0.1-plus-0.2.md"};function p(l,s,h,d,o,c){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="为什么-0-1-0-2-0-3" tabindex="-1">为什么 0.1 + 0.2 !== 0.3 <a class="header-anchor" href="#为什么-0-1-0-2-0-3" aria-label="Permalink to &quot;为什么 0.1 + 0.2 !== 0.3&quot;">​</a></h1><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 0.30000000000000004</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.2</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ===</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// false</span></span></code></pre></div><p>根因：JS 用 IEEE754 双精度二进制浮点数存小数。二进制只能精确表示分母为 2 的幂的分数（如 <code>1/2</code>、<code>1/4</code>），<code>0.1</code>（<code>1/10</code>）和 <code>0.2</code>（<code>1/5</code>）在二进制里是循环小数，存进有限位时只能截断，精度丢失，相加就不等于 <code>0.3</code>。</p><h2 id="_0-1-如何转成二进制" tabindex="-1">0.1 如何转成二进制 <a class="header-anchor" href="#_0-1-如何转成二进制" aria-label="Permalink to &quot;0.1 如何转成二进制&quot;">​</a></h2><p>十进制小数转二进制用「乘 2 取整，顺序排列」：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0.1 × 2 = 0.2  → 取整 0</span></span>
<span class="line"><span>0.2 × 2 = 0.4  → 取整 0</span></span>
<span class="line"><span>0.4 × 2 = 0.8  → 取整 0</span></span>
<span class="line"><span>0.8 × 2 = 1.6  → 取整 1</span></span>
<span class="line"><span>0.6 × 2 = 1.2  → 取整 1</span></span>
<span class="line"><span>0.2 × 2 = 0.4  → 取整 0</span></span>
<span class="line"><span>...（从 0.2 开始循环）</span></span></code></pre></div><p>所以：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0.1₁₀ = 0.0 0011 0011 0011 …₂</span></span></code></pre></div><p>是无限循环小数，计算机没法完整存下。</p><h2 id="为什么二进制除不尽" tabindex="-1">为什么二进制除不尽 <a class="header-anchor" href="#为什么二进制除不尽" aria-label="Permalink to &quot;为什么二进制除不尽&quot;">​</a></h2><p>先问一个问题：不同进制下，分母为多少时能除干净？</p><p>答案是：<strong>分母的质因子只能是当前进制的质因子</strong>。</p><ul><li><p>十进制质因子是 2、5 → <code>1/2</code>、<code>1/4</code>、<code>1/5</code>、<code>1/8</code>、<code>1/10</code> 都能除尽；<code>1/3</code>、<code>1/6</code> 则是循环小数</p></li><li><p>以 <code>1/8</code> 为例：<code>8 = 2³</code>，质因子只有 2，属于十进制的质因子。给分母补上 <code>5³</code>，就能凑成 <code>10</code> 的幂：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1/8 = 1/2³ = (1 × 5³) / (2³ × 5³) = 125 / 1000 = 0.125</span></span></code></pre></div><p>所以是有限位小数。反过来，<code>1/3</code> 的分母质因子是 3，不在 <code>{2, 5}</code> 里，怎么补也凑不成 <code>10ⁿ</code>，只能是循环小数 <code>0.333…</code></p></li><li><p>二进制质因子只有 2 → <code>1/2</code>、<code>1/4</code>、<code>1/8</code> 可以精确表示；<code>1/5</code>、<code>1/10</code> 变成循环小数，于是 <code>0.1</code>、<code>0.2</code> 在二进制里都是循环小数</p></li></ul><p>可以记一句：<strong>除不净 = 无法被精确表达</strong>。</p><p>而计算机天生只能存整数，小数要用浮点数这类近似表示。碰到除不净，只能截断，精度就丢了。因此：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.2</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> !==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.3</span></span></code></pre></div><h2 id="比较时怎么处理" tabindex="-1">比较时怎么处理 <a class="header-anchor" href="#比较时怎么处理" aria-label="Permalink to &quot;比较时怎么处理&quot;">​</a></h2><p>不要直接用 <code>===</code> 比两个浮点运算结果，用误差范围：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Math.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">abs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.2</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Number.EPSILON </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// true</span></span></code></pre></div><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><ul><li><a href="https://zhidao.baidu.com/question/583402012316514805.html" target="_blank" rel="noreferrer">0.1 如何转化为二进制 - 百度知道</a></li><li><a href="https://www.cnblogs.com/yanze/p/10113632.html" target="_blank" rel="noreferrer">0.1+0.2 为什么不等于 0.3 - 炎泽</a></li></ul>`,21)])])}const g=a(t,[["render",p]]);export{r as __pageData,g as default};
